<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_public}js/layer/layer.js"></script><style>    .layui-layer-dialog {        top: 100px !important;    }</style>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Employee/employee_list')}">从业人员列表</a>|                    <a href="{pigcms{:U('Employee/reply_list',array('employee_id'=>$employee))}"  class="on">                        <if condition="$true_name">【{pigcms{$true_name}】- </if> 评论列表                    </a>|					<a href="{pigcms{:U('Employee/employee_examine')}">审核列表</a>|                    <a href="{pigcms{:U('Employee/employee_examine_refused')}">审核拒绝列表</a>|				</ul>			</div>			<!-- <table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('Employee/employee_list')}" method="get">							<input type="hidden" name="c" value="Employee"/>							<input type="hidden" name="a" value="employee_list"/>							筛选: 							<if condition="$admin_area neq 3">							<div id="choose_pca" province_idss="{pigcms{$_GET.province_idss}" city_idss="{pigcms{$_GET.city_idss}" style="display:inline"></div>							</if>							<input type="text" name="keyword" class="input-text" value="{pigcms{$_GET['keyword']}"/>							<select name="searchtype">								<option value="true_name" <if condition="$_GET['searchtype'] eq 'true_name'">selected="selected"</if>>姓名</option>								<option value="nickname" <if condition="$_GET['searchtype'] eq 'nickname'">selected="selected"</if>>昵称</option>								<option value="phone" <if condition="$_GET['searchtype'] eq 'phone'">selected="selected"</if>>手机号</option>							</select>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;														状态:							<select name="is_open">								<option value="" <if condition="$_GET['is_open'] eq ''">selected="selected"</if>>全部</option>								<option value="1" <if condition="$_GET['is_open'] eq '1'">selected="selected"</if>>开启</option>								<option value="0" <if condition="$_GET['is_open'] eq '0'">selected="selected"</if>>关闭</option>							</select>							<input type="submit" style="margin-right:20px;" value="查询" class="button"/>							<a href="{pigcms{:U('Employee/employee_push',$_GET)}"class="button" style="margin-left: 200px;">导出用户</a>						</form>											</td>				</tr>			</table>			 -->				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>                                <th>评论者昵称</th>                                <th>从业者</th>								<th>评论内容</th>								<th>图片</th>                                <th>评论时间</th>                                <th>状态（前端是否显示）</th>                                <th>查看评论回复</th>								<th class="textcenter">操作</th>							</tr>						</thead>						<tbody>							<if condition="!empty($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.id}</td>                                        <td>{pigcms{$vo.nickname}</td>                                        <td>{pigcms{$vo.employee_name}</td>										<td>{pigcms{$vo.reply_content}</td>										<td>                                            <if condition="is_array($vo['image'])">                                                <volist name="vo['image']" id="vv">                                                    <img src="{pigcms{:file_domain()}{pigcms{$vv}" style="width: 40px;height: 40px;margin-right:5px;"  class="view_msg">                                                </volist>                                            </if>                                        </td>										<td>{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}</td>                                        <td>                                            <span class="cb-enable"><label class="cb-enable <if condition="$vo['status'] eq 0">selected</if>"><span onclick="infoSwitch('{pigcms{$vo.id}', 0)" >显示</span><input type="radio" value="0" <if condition="$vo['status'] eq 0">checked="checked"</if> /></label></span>                                            <span class="cb-disable"><label class="cb-disable <if condition="$vo['status'] eq 1">selected</if>"><span onclick="infoSwitch('{pigcms{$vo.id}', 1)">禁止</span><input type="radio" value="1" <if condition="$vo['status'] eq 1">checked="checked"</if> /></label></span>                                        </td>                                        <td>                                            <a href="{pigcms{:U('Employee/comment_reply_list',array('reply_id'=>$vo['id']))}">查看</a>                                        </td>										<td class="textcenter">										  <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Employee/reply_edit',array('reply_id'=>$vo['id'],'frame_show'=>true))}','查看信息',680,560,true,false,false,false,'detail',true);">查看</a>&nbsp;										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="8">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="8">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>		</div><script>   var url = "{pigcms{$config.site_url}";    var export_url = "{pigcms{:U('Merchant/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><script type="text/javascript">    var lockInfo = false;    function infoSwitch(reply_id, status) {        if (lockInfo) return;        lockInfo = true;        var switch_reply_status = "{pigcms{:U('Employee/switch_reply_status')}";        $.post(switch_reply_status,{reply_id:reply_id,'status': status},function(data){            console.log('data', data);            if (data && (data.status === 1 || data.status === '1')) {                location.reload();            } else {                alert(data.info)            }        },'json');        setTimeout(function(){            lockInfo = false;        },1000);    }</script><include file="Public:footer"/>